"use strict";

/**
 * createHttpHelpers — factory for URL resolution and auth helpers.
 * Replace with your actual implementation.
 */
function createHttpHelpers(requireEnv) {
  const baseUrl = (process.env.BASE_URL || "").replace(/\/$/, "");

  function resolveApiUrl(path) {
    return `${baseUrl}${path}`;
  }

  function urlToHttpStepOptions(url, method = "GET", headers = {}) {
    const parsed = new URL(url);
    return {
      hostname: parsed.hostname,
      port:     parsed.port || 443,
      method,
      path:     parsed.pathname + parsed.search,
      headers:  { "Content-Type": "application/json", ...headers },
    };
  }

  function createWithAuth(synthetics, ctx) {
    return function withAuth(options) {
      if (ctx.authToken) {
        options.headers = {
          ...options.headers,
          Authorization: `Bearer ${ctx.authToken}`,
        };
      }
      return options;
    };
  }

  return { resolveApiUrl, urlToHttpStepOptions, createWithAuth };
}

module.exports = { createHttpHelpers };
